public interface PointsAccountMapper extends BaseMapper<PointsAccount> {

    // [P02-1] 积分账户 Mapper：按 user_id 唯一键创建零余额账户，重复调用不重置余额。
    @Insert("""
            INSERT INTO points_account (
                user_id, balance, version, created_at, updated_at
            ) VALUES (
                #{userId}, 0, 0, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)
            )
            ON DUPLICATE KEY UPDATE user_id = #{userId}
            """)
    int ensureAccount(@Param("userId") long userId);

    // [P02-2] 积分账户 Mapper：把余额充足判断放进 UPDATE 条件，与扣账原子执行。
    @Update("""
            UPDATE points_account
            SET balance = balance - #{amount}, version = version + 1
            WHERE user_id = #{userId} AND balance >= #{amount}
            """)
    int debitIfSufficient(@Param("userId") long userId, @Param("amount") long amount);

    // [P02-3] 积分账户 Mapper：使用 Long.MAX_VALUE 减金额的上界保护，原子入账并递增版本。
    @Update("""
            UPDATE points_account
            SET balance = balance + #{amount}, version = version + 1
            WHERE user_id = #{userId}
              AND balance <= 9223372036854775807 - #{amount}
            """)
    int creditIfNoOverflow(@Param("userId") long userId, @Param("amount") long amount);
}

public interface PointsLedgerMapper extends BaseMapper<PointsLedger> {

    // [P02-4] 积分流水 Mapper：插入完整流水并用唯一键争抢业务占位，回填 ledger.id。
    @Insert("""
            INSERT IGNORE INTO points_ledger (
                user_id, business_type, business_id, direction, amount,
                balance_after, reversal_of_ledger_id, remark, created_at
            ) VALUES (
                #{ledger.userId}, #{ledger.businessType}, #{ledger.businessId},
                #{ledger.direction}, #{ledger.amount}, #{ledger.balanceAfter},
                #{ledger.reversalOfLedgerId}, #{ledger.remark}, CURRENT_TIMESTAMP(3)
            )
            """)
    @Options(useGeneratedKeys = true, keyProperty = "ledger.id")
    int claim(@Param("ledger") PointsLedger ledger);
}

